static Dictionary<string,string> ParseDeployArgs(string path)
{
  var map = new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
  foreach (string raw in File.ReadAllLines(path)) {
    string line = raw.Trim();
    if (line.Length==0 || line[0]=='#') continue;
    string[] parts = line.Split((char[])null, StringSplitOptions.RemoveEmptyEntries); // splits whitespace
    for (int i=0;i<parts.Length;i++) {
      string token = parts[i];
      if (!token.StartsWith("-")) continue;
      if (token.Contains('=')) {
        int eq=token.IndexOf('=');
        string key=token.Substring(0,eq).TrimStart('-');
        string val=token.Substring(eq+1).Trim();
        map[key]=Unquote(val);
      } else {
        string key=token.TrimStart('-');
        string val = (i+1<parts.Length && !parts[i+1].StartsWith("-")) ? Unquote(parts[++i]) : "";
        map[key]=val;
      }
    }
  }
  return map;
}
```
This handles line values with spaces only if quoted incorrectly; key values are URLs/keys no spaces.

