using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using LiteNet;
using LiteNet.Transport;
using LiteSync.Client;

namespace HolderClient
{
    /// <summary>
    /// 真实环境 Holder：游客登录 → 建房（4 人，避免 Editor 作为第二人入座即开局）→
    /// 真实 KCP/信封连接 → Join 后保持泵，供 RoomList 选中真实房间。
    /// </summary>
    internal static class Program
    {
        private const string DeviceId = "codex-lobby-holder";
        private const int ExpectedPlayers = 4;
        private const int MapId = 0;
        private const int LocalMetaPort = 5018;

        private const int PumpIntervalMs = 5;
        private const int JoinTimeoutMs = 30_000;
        private const int MaxRuntimeMs = 180_000;
        private const int StopPollEveryPumps = 40;      // ≈200ms 一次停止文件探测
        private const int LeaveFlushMs = 300;

        private static async Task<int> Main(string[] args)
        {
            string stopFile = ResolveStopFile(args);
            string deployArgsPath = FindDeployArgs();
            if (deployArgsPath == null) return Fail("config", 0, "deploy-args-missing");

            Dictionary<string, string> deploy;
            try { deploy = ParseDeployArgs(deployArgsPath); }
            catch { return Fail("config", 0, "deploy-args-unreadable"); }

            if (!Uri.TryCreate(Get(deploy, "meta.url"), UriKind.Absolute, out Uri metaUri) || !IsLocalMeta(metaUri))
                return Fail("meta-url", 0, "not-local-5018");

            string envelopeKey = Get(deploy, "envelope.key");
            if (string.IsNullOrWhiteSpace(envelopeKey))
                return Fail("config", 0, "envelope-key-missing");

            string metaBase = metaUri.GetLeftPart(UriPartial.Authority);
            string accessToken;
            string roomId;
            string ticket;
            string address;

            using (var http = new HttpClient { Timeout = TimeSpan.FromSeconds(20) })
            {
                string guestJson = JsonSerializer.Serialize(new { deviceId = DeviceId });
                (int guestStatus, string guestBody) = await PostJsonAsync(
                    http, metaBase + "/auth/guest", guestJson, null).ConfigureAwait(false);
                if (guestStatus < 200 || guestStatus >= 300) return Fail("guest-login", guestStatus);

                accessToken = ReadString(guestBody, "accessToken");
                if (string.IsNullOrEmpty(accessToken)) return Fail("guest-login", guestStatus, "token-missing");

                string createJson = JsonSerializer.Serialize(new
                {
                    buildHash = BuildHash.Value,
                    mapId = MapId,
                    expectedPlayers = ExpectedPlayers,
                });
                (int createStatus, string createBody) = await PostJsonAsync(
                    http, metaBase + "/lobby/create-room", createJson, accessToken).ConfigureAwait(false);
                if (createStatus < 200 || createStatus >= 300)
                    return Fail("create-room", createStatus, ReadString(createBody, "errorCode"));

                roomId = ReadString(createBody, "roomId");
                ticket = ReadString(createBody, "ticket");
                address = ReadString(createBody, "address");
            }

            if (string.IsNullOrEmpty(roomId)) return Fail("create-room", 0, "roomId-missing");
            if (string.IsNullOrEmpty(ticket)) return Fail("create-room", 0, "ticket-missing");
            if (!TryParseEndpoint(address, out string host, out int port))
                return Fail("create-room", 0, "address-invalid");

            SecureEnvelopeOptions options;
            try { options = SecureEnvelopeOptions.FromBase64(envelopeKey); }
            catch { return Fail("config", 0, "envelope-key-invalid"); }

            IClientTransport transport = null;
            RoomClient client = null;
            long started = Stopwatch.GetTimestamp();
            int pump = 0;

            try
            {
                transport = new SecureEnvelopeClientTransport(new KcpTransportClient(), options);
                client = new RoomClient(transport);

                int joinSent = 0;
                transport.OnConnected += () =>
                {
                    if (Interlocked.Exchange(ref joinSent, 1) == 0)
                        client.SendJoin(roomId, ticket, BuildHash.Value);
                };

                client.Connect(host, port);

                while (client.PlayerId < 0)
                {
                    client.TickIncoming();
                    client.TickOutgoing();
                    pump++;

                    if (ElapsedMs(started) >= JoinTimeoutMs) return Fail("join", 0, "timeout");
                    if (ElapsedMs(started) >= MaxRuntimeMs) return Fail("join", 0, "runtime-limit");
                    if (pump % StopPollEveryPumps == 0 && File.Exists(stopFile)) return 0;

                    Thread.Sleep(PumpIntervalMs);
                }

                Console.Out.WriteLine($"READY roomId={roomId} playerId={client.PlayerId}");
                Console.Out.Flush();

                while (ElapsedMs(started) < MaxRuntimeMs)
                {
                    client.TickIncoming();
                    client.TickOutgoing();

                    if (client.Phase == ClientSessionPhase.SuspectedLost)
                        client.BeginReconnect();
                    else if (client.Phase == ClientSessionPhase.Restoring)
                        client.CompleteRestore();
                    else if (client.Phase == ClientSessionPhase.Failed)
                        return Fail("session", 0, "failed");

                    pump++;
                    if (pump % StopPollEveryPumps == 0 && File.Exists(stopFile)) break;

                    Thread.Sleep(PumpIntervalMs);
                }

                return 0;
            }
            catch (Exception ex)
            {
                return Fail("runtime", 0, ex.GetType().Name);
            }
            finally
            {
                if (client != null)
                {
                    try { client.SendLeave(); } catch { }
                    for (int i = 0; i < LeaveFlushMs / PumpIntervalMs; i++)
                    {
                        try
                        {
                            client.TickIncoming();
                            client.TickOutgoing();
                        }
                        catch { }
                        Thread.Sleep(PumpIntervalMs);
                    }
                    try { client.Dispose(); } catch { }
                }

                if (transport != null)
                {
                    try { transport.Dispose(); } catch { }
                }
            }
        }

        private static long ElapsedMs(long started)
            => (Stopwatch.GetTimestamp() - started) * 1000L / Stopwatch.Frequency;

        private static string ResolveStopFile(string[] args)
        {
            string path = null;
            for (int i = 0; i < args.Length; i++)
            {
                if (args[i] == "--stop-file" && i + 1 < args.Length)
                {
                    path = args[++i];
                    continue;
                }
                if (!args[i].StartsWith("--", StringComparison.Ordinal) && path == null)
                    path = args[i];
            }

            if (string.IsNullOrWhiteSpace(path))
                path = Environment.GetEnvironmentVariable("LITE_HOLDER_STOP_FILE");
            if (string.IsNullOrWhiteSpace(path))
                path = Path.Combine(Path.GetTempPath(), "lobby-holder.stop");

            return Path.GetFullPath(path);
        }

        private static string FindDeployArgs()
        {
            foreach (string start in new[] { AppContext.BaseDirectory, Environment.CurrentDirectory })
            {
                DirectoryInfo d
